'use strict';
function contextSettingsHtml(){return `<div class="settings-section"><h3>Контекст и длина ответа</h3><p class="form-help">Общий бюджет для запроса, истории, инструментов и ответа. Авто расширяет окно до заданного предела с учётом возможностей модели. Большее окно требует больше RAM/VRAM; доступность памяти не гарантируется.</p><div class="form-row"><div><label class="form-label" for="context-window">Окно контекста</label><select id="context-window"><option value="0">Авто</option>${[4096,8192,16384,32768,65536,131072,262144].map(n=>`<option value="${n}">${n.toLocaleString('ru')} токенов</option>`).join('')}</select></div><div><label class="form-label" for="context-auto-max">Предел Авто</label><input class="full-input" id="context-auto-max" type="number" min="8192" max="262144" step="1"></div></div><label class="form-label" for="context-output">Резерв ответа, токенов</label><input class="full-input" id="context-output" type="number" min="512" max="32768" step="1"><p class="form-help">С рассуждениями резерв составляет не менее 8192 токенов, если окно позволяет. Текущий запрос не обрезается. Старые диалоги сокращаются целыми ходами; большие вложения для ревью разбираются по частям. Подсчёт до запуска приблизительный, фактический расход доступен под ответом.</p></div>`;}
function loadContextSettings(){const c=state.settings.context||{};const window=$('#context-window'),value=String(c.window_tokens??0);if(![...window.options].some(o=>o.value===value))window.add(new Option(value,value));window.value=value;$('#context-auto-max').value=c.auto_max_tokens??32768;$('#context-output').value=c.output_tokens??4096;}
function contextSelection(){return {window_tokens:Number($('#context-window').value),auto_max_tokens:Number($('#context-auto-max').value),output_tokens:Number($('#context-output').value)};}
function contextReportHtml(d){const calls=d?.inferences||[],last=calls.at(-1)||d,c=last?.context;if(!c)return '';const usage=last?.usage||{};return `<details class="assistant-report"><summary>Контекст ${Number(c.window_tokens).toLocaleString('ru')} · резерв ответа ${Number(c.output_tokens).toLocaleString('ru')}${d?.length_limited?' · ответ не завершён':''}</summary><p>Запрос: ${usage.prompt_eval_count??'около '+c.input_estimate} токенов. Ответ: ${usage.eval_count??'нет данных'} токенов.${calls.length>1?' Запусков при анализе частей: '+calls.length+'.':''} Подсчёт до запуска приблизительный; фактический расход сообщает движок.</p><pre>${escapeHtml(JSON.stringify({context:c,usage},null,2))}</pre></details>`;}
