function toast(message, error=false) {
  const element=document.createElement('div');element.className='toast'+(error?' error':'');element.textContent=message;$('#toasts').append(element);setTimeout(()=>element.remove(),7000);
}
async function api(path, options={}) {
  const headers={'X-Studio-Token':state.token,...options.headers};
  if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  const response=await fetch(path,{...options,headers});
  if(!response.ok){const error=await response.json().catch(()=>({error:response.statusText}));const failure=new Error(error.error||response.statusText);failure.status=response.status;throw failure;}
  return response.json();
}
async function consumeEvents(path, body, onEvent, options={}) {
  let cursor=options.cursor||0, terminal=false, reconnect=options.persistent?'workspace':body?.request_id||path.match(/^\/api\/runs\/([^/]+)\/events/)?.[1]||null;
  while(!terminal){
    let response;
    try {
      response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Studio-Token':state.token},...(body===undefined?{}:{body:JSON.stringify(body)})});
      if(!response.ok){const detail=await response.json().catch(()=>({error:response.statusText}));const error=new Error(detail.error||response.statusText);error.http=true;throw error;}
      const reader=response.body.getReader(), decoder=new TextDecoder();let buffer='';
      while(true){const{done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let position;
        while((position=buffer.indexOf('\n\n'))!==-1){const block=buffer.slice(0,position);buffer=buffer.slice(position+2);const data=block.split('\n').filter(s=>s.startsWith('data:')).map(s=>s.slice(5).trimStart()).join('\n');if(!data)continue;const event=JSON.parse(data);if(event.sequence&&event.sequence<=cursor)continue;await onEvent(event);cursor=event.sequence||cursor;if(event.type==='start'&&!options.persistent)reconnect=event.run_id;if(event.type==='done'&&!options.persistent)terminal=true;}
      }
      if(terminal||!reconnect)return;
    }catch(error){if(error.http||!reconnect)throw error;}
    await new Promise(resolve=>setTimeout(resolve,1000));
    path=options.persistent?'/api/events?after='+cursor:'/api/runs/'+reconnect+'/events?after='+cursor;body=undefined;
  }
}

