function updateSend(){renderActiveModel();renderApprovalShortcut();renderTaskIntent();renderSearchMode();document.querySelectorAll('[data-mode]').forEach(button=>button.disabled=state.busy);if(typeof refreshToolControls==='function')refreshToolControls();$('#model-name').disabled=state.busy||modelMenuSaving||(state.mode==='search'&&searchOptions().depth==='results');if(state.busy)closeModelMenu();const send=$('#send');send.classList.toggle('stop',state.busy);send.innerHTML=icon(state.busy?'stop':'arrow');send.setAttribute('aria-label',state.busy?'Остановить ответ':'Отправить');send.disabled=!state.busy&&(!$('#prompt').value.trim()&&!state.pending.length||state.uploading>0||state.pendingInput>0);}
function resizeInput(){const prompt=$('#prompt');prompt.style.height='auto';prompt.style.height=Math.min(220,prompt.scrollHeight)+'px';updateSend();currentSession().draft=prompt.value;persistDraft();}
let chatsRequest=0;async function refreshChats(){const request=++chatsRequest;const chats=await api('/api/chats');if(request!==chatsRequest)return;for(const[id,session]of viewSessions){if((session.busy||session.sending)&&session.chat&&!chats.some(chat=>chat.id===id))chats.unshift(session.chat);}state.chats=chats;renderChats();}
