async function handleRunEvent(event,clearDraft=false,session=currentSession(),conversation=visibleConversation()){
    if(event.sequence&&(event.sequence<=(session.ignoreThrough||0)))return;
    const visible=visibleConversation()===conversation;const schedule=()=>{trimRunView(session);if(visible)scheduleStream();};
    switch(event.type){case 'start':session.acceptedOptions=event.accepted||session.acceptedOptions;session.busy=true;session.runMode=event.mode||session.runMode;session.startedAt=session.startedAt||Date.now();session.run=event.run_id;session.notice='Запрос принят';if(session.submission?.request_id===event.run_id&&!session.submission.retry)clearAcceptedDraft(session,conversation,session.submission);if(visible){if(modes[session.runMode])setMode(session.runMode);if(session.runMode==='search')$('#search-preferences').open=false;renderMessages();updateSend();startResponseTimer();}renderChats();break;
      case 'replace_content':session.textOffset=0;session.streamText=event.text;session.notice='';schedule();break;
      case 'model_context':session.notice='Подготовка модели';schedule();break;
      case 'thinking':session.streamThinking=(session.streamThinking||'')+event.text;session.notice='Рассуждение…';schedule();break;
      case 'token':session.streamText+=event.text;session.notice='Генерация ответа…';schedule();break;
      case 'notice':session.notice=event.message;schedule();break;
      case 'progress':session.notice=event.message||'Обработка документа…';schedule();break;
      case 'extracted':session.toolsTotal=(session.toolsTotal||0)+1;session.streamTools.push({id:event.id,name:'Вложение: '+event.name,arguments:{file:event.name},result:event.text,material_artifact:event.material_artifact,status:'succeeded'});schedule();break;
      case 'tool_start':session.toolsTotal=(session.toolsTotal||0)+1;session.streamTools.push({id:event.id,name:event.name,arguments:event.arguments,arguments_artifact:event.arguments_artifact,status:event.status||'running'});session.notice='Выполняется: '+toolTitle(event.name);schedule();break;
      case 'tool_result':{const tool=[...session.streamTools].reverse().find(t=>event.tool.id?t.id===event.tool.id:t.name===event.tool.name&&t.result===undefined);if(tool)Object.assign(tool,event.tool);else{session.toolsTotal=(session.toolsTotal||0)+1;session.streamTools.push(event.tool);}session.notice=event.tool.status==='succeeded'?'Обработка результата…':event.tool.status==='denied'?'Действие отклонено':event.tool.status==='failed'?'Ошибка действия':'Завершение действия…';schedule();break;}
      case 'approval':{const tool=session.streamTools.find(t=>t.id===event.tool_id);if(tool)tool.status='awaiting_approval';}session.approvals.push(event);renderChats();toast('Агент ожидает вашего подтверждения.');session.notice='Ожидается ваше подтверждение';schedule();break;
      case 'approval_closed':{const tool=session.streamTools.find(t=>t.id===event.tool_id);if(tool)tool.status=event.status||(event.allowed?'running':'denied');}session.approvals=session.approvals.filter(a=>a.id!==event.id);session.notice=event.allowed?'Выполняется действие…':'Действие не выполняется';schedule();break;
      case 'saved':if(event.conversation?.messages){session.chat=event.conversation;if(visible){state.chat=event.conversation;$('#chat-title').textContent=state.chat.title;}}break;
      case 'done':await finishConversationRun(session,conversation,event.run_id||session.run);break;
      case 'error':toast(event.message,true);break;
    }
}
async function reconnectRun(){return connectWorkspace();}
async function stopRun(){const session=currentSession();if(session.submitting){session.cancelRequested=true;session.notice='Остановка после приёма запроса…';scheduleStream();return;}if(session.run){await api('/api/stop/'+session.run,{method:'POST',body:{}});session.notice='Остановка…';scheduleStream();}}

async function uploadFiles(files,target){const own=!target;target ||= inputDestination();const {session,id}=target;const visible=()=>visibleConversation()===id;try{for(const file of Array.from(files)){if(file.size>80*1024*1024){toast(file.name+': больше 80 МБ',true);continue;}session.uploading++;if(visible())renderPending();try{const form=new FormData();form.append('file',file,file.name);const attachment=await api('/api/upload',{method:'POST',body:form});session.pending.push(attachment);persistDraft(id,session);}catch(error){toast(error.message,true);}finally{session.uploading--;if(visible())renderPending();}}}finally{if(own)releaseInput(target);}if(visible())$('#prompt').focus();}

function insertText(text){const prompt=$('#prompt');prompt.focus();const start=prompt.selectionStart,end=prompt.selectionEnd;prompt.setRangeText(text,start,end,'end');resizeInput();}
async function copy(text){try{await navigator.clipboard.writeText(text);}catch{const active=document.activeElement,selection=getSelection(),ranges=[];for(let i=0;i<(selection?.rangeCount||0);i++)ranges.push(selection.getRangeAt(i).cloneRange());const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;opacity:0;pointer-events:none';document.body.append(area);area.select();let copied=false;try{copied=document.execCommand('copy');}catch{}finally{area.remove();}active?.focus({preventScroll:true});if(selection&&ranges.length){selection.removeAllRanges();ranges.forEach(range=>selection.addRange(range));}if(!copied){toast('Не удалось скопировать текст. Выделите его и используйте системную команду копирования.',true);return false;}}toast('Скопировано');return true;}

function download(text,name,type='text/markdown;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportChat(){if(!state.chat){toast('Сначала начните диалог.');return;}const text='# '+state.chat.title+'\n\n'+state.chat.messages.map(message=>'## '+(message.role==='user'?'Вы':modelName(message.model)||'Gemma')+'\n\n'+message.content+(message.attachments?.length?'\n\nВложения: '+message.attachments.map(a=>a.name).join(', '):'')+(message.tools?.length?'\n\n'+message.tools.map(t=>'<details>\n<summary>'+t.name+'</summary>\n\n```text\n'+t.result+'\n```\n</details>').join('\n\n'):'')).join('\n\n---\n\n');download(text,(state.chat.title.replace(/[<>:"/\\|?*]/g,'').slice(0,65)||'chat')+'.md');}
