 $('#compute-packages').innerHTML=computeInfo.package_install_supported?[['vulkan','Vulkan · NVIDIA / AMD / Intel','около 40 МБ',devices.some(d=>d.backend==='vulkan')],['cuda','CUDA · NVIDIA','около 2 ГБ',devices.some(d=>d.backend==='cuda')],['rocm','ROCm · AMD','около 1 ГБ',amd]].map(([backend,name,size,found])=>`<div class="compute-package"><div><strong>${name}</strong><span>${computeInfo.packages[backend]?'Модуль установлен':found?'Компоненты отдельно · '+size:'Подходящее устройство не обнаружено'}</span></div>${!computeInfo.packages[backend]?`<button class="button" data-install-compute="${backend}" ${!found||computeInstalling?'disabled':''}>Скачать модуль</button>`:'<span class="installed-mark">Готово</span>'}</div>`).join(''):'<p class="form-help">На этой платформе библиотеки GPU поставляются вместе с Ollama.</p>';
