async function openDocument(item){if(documentState.busy||documentState.reading){toast('Дождитесь обработки документа.');return;}Object.assign(documentState,{item,read:null,run:null,output:null});documentState.session++;$('#document-title').textContent=item.name;const pdf=item.name.toLowerCase().endsWith('.pdf');$('#document-pages').classList.toggle('hidden',!pdf);$('#document-ocr-row').classList.toggle('hidden',!pdf);$('#document-next').classList.toggle('hidden',!pdf);$('#document-start').value=1;$('#document-count').value=5;$('#document-ocr').checked=false;$('#document-source').value=state.settings.source||'en';$('#document-target').value=state.settings.target||'ru';$('#document-result').classList.add('hidden');$('#document-text').textContent='';$('#document-progress').textContent='';$('#document-warnings').textContent='';$('#document-information').textContent='';$('#document-model').textContent='Переводчик: '+modelName(state.settings.translation_model)+'. '+(pdf?'Выгрузка выбранных страниц в Markdown.':'Перевод абзацами в DOCX: до 300 абзацев / 40000 символов; до 4000 символов в одном абзаце.');$('#document-translate').textContent=pdf?'Перевести выбранные страницы':'Перевести DOCX';$('#document-dialog').showModal();await readDocument();}
async function readDocument(){if(documentState.busy||documentState.reading)return;documentState.reading=true;const session=documentState.session;documentState.run=crypto.randomUUID();const readJob=documentState.run;$('#document-progress').textContent='Чтение документа…';documentControls();try{const result=await api('/api/documents/read',{method:'POST',body:{...documentOptions(),job:readJob}});if(session!==documentState.session)return;documentState.read=result;$('#document-text').textContent=result.text||'';$('#document-information').textContent=result.format==='pdf'?`Страницы ${result.start_page}–${result.end_page} из ${result.total_pages}${result.has_more?' · есть продолжение':''}`:`Абзацев: ${result.paragraphs_count??result.units_count} · текстовых участков: ${result.units_count}${result.complete?'':' · чтение сокращено'}`;$('#document-warnings').textContent=(result.warnings||[]).join(' ');$('#document-progress').textContent='Текст извлечён локально.';}catch(error){if(session===documentState.session)$('#document-progress').textContent=error.message;}finally{documentState.reading=false;if(documentState.run===readJob)documentState.run=null;documentControls();}}
async function translateDocument(){if(documentState.busy||documentState.reading||state.busy||state.downloading){toast('Дождитесь текущей операции.');return;}documentState.busy=true;documentState.output=null;const session=documentState.session;$('#document-result').classList.add('hidden');$('#document-progress').textContent='Подготовка перевода…';documentControls();try{await consumeEvents('/api/documents/translate',documentOptions(),event=>{if(session!==documentState.session)return;if(event.type==='start'){documentState.run=event.run_id;documentControls();}if(event.type==='progress')$('#document-progress').textContent=event.message+(event.total?` · ${event.completed}/${event.total}`:'');if(event.type==='error')throw new Error(event.message);if(event.type==='document_result'){documentState.output=event.attachment;$('#document-download').href='/api/files/'+event.attachment.id;$('#document-download').download=event.attachment.name;$('#document-report').textContent=`Обработано ${event.report.unit_kind==='paragraph'?'абзацев':'страниц'}: ${event.report.processed_units||0}. Переведено моделью: ${event.report.translated_units||0}. Запросов перевода: ${event.report.inference_calls??event.report.translated_units??0}${event.report.format_retries?` (повторов форматирования: ${event.report.format_retries})`:''}. `+(event.report.warnings||[]).join(' ');$('#document-result').classList.remove('hidden');$('#document-result').scrollIntoView({block:'nearest'});}});}catch(error){if(session===documentState.session)$('#document-progress').textContent=error.message;}finally{documentState.busy=false;documentState.run=null;documentControls();}}
