async function preview(id){const attachment=[...state.pending,...(state.chat?.messages||[]).flatMap(m=>m.attachments||[])].find(a=>a.id===id);if(!attachment)return;if(attachment.kind==='document'){await openDocument(attachment);return;}$('#preview-title').textContent=attachment.name;const body=$('#preview-body');body.replaceChildren();if(attachment.kind==='image'){const image=document.createElement('img');image.className='preview-img';image.src='/api/files/'+id;image.alt=attachment.name;body.append(image);}else if(attachment.kind==='audio'){const audio=document.createElement('audio');audio.controls=true;audio.src='/api/files/'+id;audio.style.width='100%';body.append(audio);}else if(attachment.kind==='text'){const text=await(await fetch('/api/files/'+id)).text();const content=document.createElement('div');content.className='message-body';const formatted=/\.(md|markdown)$/i.test(attachment.name);let raw=!formatted;const render=()=>{content.replaceChildren();if(raw){const pre=document.createElement('pre'),code=document.createElement('code');code.className='language-plaintext';code.textContent=text;pre.append(code);content.append(pre);}else content.innerHTML=markdown(text);enhanceMarkdown(content);};if(formatted){const toggle=document.createElement('button');toggle.className='button';toggle.textContent='Показать исходный текст';toggle.onclick=()=>{raw=!raw;render();toggle.textContent=raw?'Показать с форматированием':'Показать исходный текст';};body.append(toggle);}body.append(content);render();}else{const p=document.createElement('p');p.textContent='Предпросмотр этого формата не поддерживается.';body.append(p);}const link=document.createElement('a');link.href='/api/files/'+id;link.download=attachment.name;link.textContent='Скачать файл';link.className='button';link.style.marginTop='18px';body.append(link);$('#preview-dialog').showModal();}
