async function pullModels(model=null){if(state.downloading)return;state.downloading=true;const progress=$('#pull-progress');progress.textContent='Подключение к Ollama…';document.querySelectorAll('[data-download-model],[data-action="pull"]').forEach(b=>b.disabled=true);let failed=false;try{await consumeEvents('/api/models/pull',model?{model,directory:modelDirectories.get(model)||state.status?.model_locations?.[model]||''}:{},event=>{if(event.type==='progress'){const item=event.progress;progress.textContent=modelName(event.model)+'\n'+item.status+(item.total?' · '+Math.floor(100*(item.completed||0)/item.total)+'%':'');}if(event.type==='error'){failed=true;throw new Error(event.message);}});if(!failed)progress.textContent='Скачивание завершено. Модель можно выбрать для нужной задачи.';}catch(error){progress.textContent='Не удалось скачать: '+error.message;}finally{state.downloading=false;await refreshStatus();document.querySelectorAll('[data-action="pull"]').forEach(b=>b.disabled=false);}}


function bindEvents(){
  bindModelMenu();
  uiListen($('#prompt'),'input',resizeInput);uiListen($('#prompt'),'keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&!state.busy){event.preventDefault();send().catch(e=>toast(e.message,true));}});
  uiListen(document,'paste',event=>{if(document.querySelector('dialog[open]'))return;const files=Array.from(event.clipboardData?.items||[]).filter(item=>item.kind==='file').map(item=>item.getAsFile()).filter(Boolean);if(files.length){event.preventDefault();uploadFiles(files);}else if(!event.clipboardData?.getData('text/plain')&&event.target===$('#prompt')){event.preventDefault();pasteNative().catch(e=>toast(e.message,true));}});
  uiListen($('#file-input'),'change',event=>{uploadFiles(event.target.files);event.target.value='';});uiListen($('#chat-search'),'input',renderChats);
  uiListen($('#scroll'),'scroll',()=>{const scroll=$('#scroll');state.scrollFollow=scroll.scrollHeight-scroll.scrollTop-scroll.clientHeight<140;});
  let dragCounter=0;uiListen(document,'dragenter',event=>{if(event.dataTransfer?.types?.includes('Files')){event.preventDefault();dragCounter++;$('#drop-overlay').classList.add('active');}});uiListen(document,'dragover',event=>{if(event.dataTransfer?.types?.includes('Files'))event.preventDefault();});uiListen(document,'dragleave',()=>{dragCounter=Math.max(0,dragCounter-1);if(!dragCounter)$('#drop-overlay').classList.remove('active');});uiListen(document,'drop',event=>{event.preventDefault();dragCounter=0;$('#drop-overlay').classList.remove('active');if(event.dataTransfer?.files.length)uploadFiles(event.dataTransfer.files);});
  uiListen(document,'keydown',handleGlobalShortcut);
  uiListen($('#document-dialog'),'cancel',event=>{event.preventDefault();closeDocument();});
  uiListen($('#voice-dialog'),'cancel',event=>{event.preventDefault();closeVoice();});
  uiListen(document,'click',async event=>{const button=event.target.closest('button,[data-preview]');if(!event.target.closest('.context-menu')&&!event.target.closest('[data-chat-menu]'))document.querySelector('.context-menu')?.remove();if(!button)return;
    try{
      if(button.dataset.deleteModel){
        const model=button.dataset.deleteModel;
        let dialog=$('#delete-model-dialog');
        if(!dialog){dialog=document.createElement('dialog');dialog.id='delete-model-dialog';dialog.innerHTML='<div class="dialog-head"><h2>Удалить модель?</h2></div><div class="dialog-body"><p id="delete-model-description"></p><p class="form-help">Её можно скачать снова. Переписка и файлы сохранятся. Если модель выбрана для задачи, перед следующим запросом выберите другую или скачайте её заново.</p></div><div class="dialog-foot"><button class="button" data-close="delete-model-dialog">Отмена</button><button class="button danger" id="delete-model-confirm">Удалить</button></div>';document.body.append(dialog);}
        $('#delete-model-description').textContent=modelName(model);
        $('#delete-model-confirm').onclick=async()=>{const confirm=$('#delete-model-confirm');confirm.disabled=true;try{await api('/api/models/delete',{method:'POST',body:{model}});dialog.close();await refreshStatus();toast('Модель удалена');}catch(error){toast(error.message,true);}finally{confirm.disabled=false;}};
        dialog.showModal();return;
      }
      if(button.dataset.downloadModel)return await pullModels(button.dataset.downloadModel);
      if(button.dataset.mode){if(state.busy){toast('Режим можно сменить после завершения ответа.');return;}setMode(button.dataset.mode);return;}
      if(button.dataset.chat)return await selectChat(button.dataset.chat);
      if(button.dataset.chatMenu)return chatMenu(button.dataset.chatMenu,button);
      if(button.dataset.remove){state.pending=state.pending.filter(a=>a.id!==button.dataset.remove);renderPending();return;}
      if(button.dataset.preview)return await preview(button.dataset.preview);
      if(button.dataset.artifact)return await showArtifact(button.dataset.artifact);
      if(button.dataset.processView)return await showProcess(button.dataset.processView);
      if(button.dataset.treeDirectory!==undefined){await refreshTree(button.dataset.treeDirectory);return;}
      if(button.dataset.treeCursor){await refreshTree(filePage?.directory||'',button.dataset.treeCursor);return;}
      if(button.dataset.treePath){insertText('`'+button.dataset.treePath+'`');return;}
      if(button.dataset.close){$('#'+button.dataset.close).close();return;}
      if(button.hasAttribute('data-copy-tool-text'))return await copy(button.closest('.tool-file').querySelector('pre').textContent);
      if(button.hasAttribute('data-copy-code'))return await copy(button.closest('.code-block').querySelector('code').textContent);
      if(button.dataset.copyMessage!==undefined)return await copy(state.chat.messages[+button.dataset.copyMessage].content);
      if(button.dataset.saveMessage!==undefined)return download(state.chat.messages[+button.dataset.saveMessage].content,'message.md');
      if(button.dataset.editMessage!==undefined){$('#prompt').value=state.chat.messages[+button.dataset.editMessage].content;resizeInput();$('#prompt').focus();return;}
      if(button.dataset.installCompute){await installCompute(button.dataset.installCompute);return;}
      if(button.dataset.projectGit){await projectGit(button.dataset.projectGit);return;}
      if(button.dataset.projectCommand){insertText('Запусти проверку в папке '+JSON.stringify(button.dataset.projectDirectory)+': '+button.dataset.projectCommand);$('#projects-dialog').close();return;}
      if(button.dataset.downloadExecution){await downloadExecution(button.dataset.downloadExecution);return;}
      if(button.dataset.restoreChange){button.disabled=true;try{await restoreChange(button.dataset.restoreChange);}finally{button.disabled=false;}return;}
      if(button.dataset.revokePermission){await api('/api/permissions/'+button.dataset.revokePermission+'/revoke',{method:'POST',body:{}});await loadPermissionGrants();return;}
      if(button.dataset.materialSources){const message=state.chat?.messages.find(item=>item.id===button.dataset.materialSources);if(message)showMaterialList(message.diagnostics?.material_sources||[]);return;}
      if(button.dataset.sourceIndex){await showSourceIndex(button.dataset.sourceIndex);return;}
      if(button.dataset.toolHistory||button.dataset.runText){await showRunHistory(button.dataset.toolHistory||button.dataset.runText,button.dataset.kind||'tools');return;}
      if(button.dataset.localToolHistory!==undefined){await showRunHistory(null,'tools',state.chat.messages[Number(button.dataset.localToolHistory)].tools);return;}
      if(button.dataset.approvalPreview){await showApprovalPreview(button.dataset.approvalPreview);return;}
      if(button.dataset.approve||button.dataset.deny){const id=button.dataset.approve||button.dataset.deny;const buttons=button.closest('.approval-actions').querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await api('/api/approve/'+id,{method:'POST',body:{allow:!!button.dataset.approve,duration:button.closest('[data-approval-card]').querySelector('[data-grant-duration]')?.value||'once'}});}catch(error){buttons.forEach(b=>b.disabled=false);throw error;}return;}
      if(button.dataset.renameChat){const id=button.dataset.renameChat;const chat=state.chats.find(c=>c.id===id);document.querySelector('.context-menu')?.remove();editDialog('Название чата',chat.title,'Сохранить',async title=>{await api('/api/chats/'+id,{method:'PATCH',body:{title}});if(state.chat?.id===id){state.chat.title=title;$('#chat-title').textContent=title;}await refreshChats();});return;}
      if(button.dataset.deleteChat){const id=button.dataset.deleteChat;document.querySelector('.context-menu')?.remove();editDialog('Удалить чат?','История этого диалога будет удалена.','Удалить',async()=>{await api('/api/chats/'+id,{method:'DELETE'});if(state.chat?.id===id)newChat();await refreshChats();});return;}
      if(button.dataset.suggestion){const suggestion=button.dataset.suggestion;if(suggestion==='translate'){setMode('translate');$('#prompt').focus();}if(suggestion==='image'){$('#file-input').accept='image/*';$('#file-input').click();}if(suggestion==='audio')openVoice();if(suggestion==='agent'){setMode('agent');$('#prompt').value='Посмотри файлы в рабочей папке и расскажи, как устроен проект.';resizeInput();$('#prompt').focus();}return;}
      switch(button.dataset.action){case 'tasks':await showTaskState();break;case 'read-document':await readDocument();break;case 'next-document':$('#document-start').value=documentState.read?.next_page||1;await readDocument();break;case 'insert-document':if(documentState.read?.text){insertText(documentState.read.text);await closeDocument();}break;case 'translate-document':await translateDocument();break;case 'stop-document':await stopDocument();break;case 'close-document':await closeDocument();break;case 'attach-document-result':if(documentState.output){if(!state.pending.some(a=>a.id===documentState.output.id))state.pending.push(documentState.output);renderPending();await closeDocument();}break;case 'install-browser':await installBrowserComponents();break;case 'assistant-config':await showAssistantConfig();break;case 'refresh-hardware':await loadCompute(true);break;case 'retry-compute':await retryCompute();break;case 'projects':await showProjects();break;case 'inspect-project':await inspectProject();break;case 'use-project':await useProject();break;case 'changes':await showChanges();break;case 'quick-help':toast('Выделите текст в другом приложении и нажмите '+(state.settings.quick_hotkey||'Control+Shift+T')+'. Для обычного копирования доступен переводчик: '+location.origin+'/quick.html');break;case 'new-chat':newChat();break;case 'sidebar':setSidebarOpen(document.body.classList.contains('sidebar-hidden'));break;case 'files':await toggleFiles();break;case 'settings':await showSettings();break;case 'save-settings':await saveSettings();break;case 'export':exportChat();break;case 'attach':$('#file-input').accept='';$('#file-input').click();break;case 'paste':await pasteClipboard();break;case 'send':await send();break;case 'retry':await send(true);break;case 'swap':{const source=$('#source').value;$('#source').value=$('#target').value;$('#target').value=source;break;}case 'pull':await pullModels();break;case 'voice':openVoice();break;case 'record':await startRecord();break;case 'system-record':await systemRecord();break;case 'close-voice':await closeVoice();break;case 'use-voice':await useVoice();break;}
    }catch(error){toast(error.message,true);}
  });
}
async function boot(){try{
  const bootstrap=await api('/api/bootstrap');state.token=bootstrap.token;state.localInference=bootstrap.local_inference;state.platform=bootstrap.platform;state.settings=bootstrap.settings;state.catalog=bootstrap.catalog||[];
  state.chats=await api('/api/chats');const last=localStorage.getItem('gemma.lastChat');state.chat=last&&state.chats.some(chat=>chat.id===last)?await api('/api/chats/'+last):null;
  state.mode=state.chat?.mode||localStorage.getItem('gemma.mode')||'agent';if(!modes[state.mode])state.mode='agent';
  buildShell();updateWorkspace();renderChats();renderMessages();if(state.chat)$('#chat-title').textContent=state.chat.title;
  if(!readDraft(visibleConversation())&&localStorage.getItem('gemma.draft')){$('#prompt').value=localStorage.getItem('gemma.draft');resizeInput();localStorage.removeItem('gemma.draft');}else restoreDraft();
  reconnectRun().catch(error=>toast(error.message,true));refreshStatus();state.statusTimer=setInterval(refreshStatus,15000);
}catch(error){$('#app').innerHTML=`<div class="boot">Не удалось подключиться<span>${escapeHtml(error.message)}</span><button class="button" id="boot-retry">Подключиться снова</button></div>`;$('#boot-retry').onclick=boot;}}
boot();
